"use client";import{FormEvent,useEffect,useState}from"react";import type{Article}from"../../../lib/article-content";const fresh=():Article=>({id:crypto.randomUUID(),slug:"مقاله-جدید",title:"عنوان مقاله",excerpt:"خلاصه مقاله",content:"متن کامل مقاله",image:"/images/packages.jpg",date:new Date().toLocaleDateString("fa-IR")});export default function AdminArticles(){const[a,setA]=useState<Article[]>([]),[m,setM]=useState("");useEffect(()=>{fetch("/api/articles").then(r=>r.json()).then(setA)},[]);const edit=(i:number,k:keyof Article,v:string)=>setA(o=>o.map((x,n)=>n===i?{...x,[k]:v}:x));async function save(e:FormEvent){e.preventDefault();const r=await fetch("/api/articles",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(a)});setM(r.ok?"مقالات ذخیره شدند.":"ذخیره انجام نشد.");}return <main className="admin"><div className="adminHead"><h1>مدیریت مقالات</h1><a href="/articles" target="_blank">مشاهده مقالات</a></div><form className="editor" onSubmit={save}>{a.map((x,i)=><section key={x.id}><div className="productTitle"><h2>مقاله {i+1}</h2><button type="button" className="danger" onClick={()=>setA(o=>o.filter((_,n)=>n!==i))}>حذف</button></div>{([['title','عنوان'],['slug','آدرس انگلیسی/فارسی'],['date','تاریخ'],['image','آدرس تصویر'],['excerpt','خلاصه'],['content','متن کامل']] as [keyof Article,string][]).map(([k,l])=><label key={k}>{l}{k==='excerpt'||k==='content'?<textarea value={x[k] as string} onChange={e=>edit(i,k,e.target.value)}/>:<input value={x[k] as string} onChange={e=>edit(i,k,e.target.value)}/>}</label>)}</section>)}<button type="button" className="addProduct" onClick={()=>setA(o=>[...o,fresh()])}>+ افزودن مقاله</button><button className="save">ذخیره تغییرات</button>{m&&<p className="status">{m}</p>}</form></main>}
